DO $demo$
DECLARE p record; b record; routine_id uuid; request_id uuid; cleaning_id uuid; start_at timestamptz; ready_at timestamptz;
BEGIN
 FOR p IN SELECT "Id","Name","Timezone" FROM casazen_test."Properties" WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "Id" IN ('36e556c2-943e-44d7-86db-dea0567ea8a1','36e556c2-943e-44d7-86db-dea0567ea8a2','36e556c2-943e-44d7-86db-dea0567ea8a3') LOOP
