 jsonb_build_object('version','1.0','groups',jsonb_build_array(jsonb_build_object('operator','AND','rules',jsonb_build_array(jsonb_build_object('fieldId','propertyId','operator','in','value',jsonb_build_array(p."Id"::text))))))::text,
