 FOR b IN SELECT "Id","CheckOutDate" FROM casazen_test."Bookings" WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "PropertyId"=p."Id" AND "Status"=3 LOOP
