 cleaning_id=md5('quokka-demo-stay-cleaning:'||b."Id"::text)::uuid;
 start_at=(b."CheckOutDate"::date+time '10:00') AT TIME ZONE coalesce(nullif(p."Timezone",''),'Europe/Rome');
 ready_at=start_at+interval '2 hours 15 minutes';
