 UPDATE casazen_test."Bookings" SET "CheckedOutAt"=start_at,"UpdatedAt"=now() WHERE "Id"=b."Id" AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."InternalActivities" SET "ScheduledAt"=start_at,"CompletedAt"=start_at+interval '2 hours',"Status"='Completed',"Notes"='TEST - Pulizia completata dal fornitore abituale Quokka Housekeeping; immobile nuovamente pronto.' WHERE "BookingId"=b."Id" AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "ActivityType"='Cleaning';
